module snuke_string_counter (\n    input clk,\n    input rst_n,\n    input start,\n    input [3:0] N,\n    input c_AA,\n    input c_AB,\n    input c_BA,\n    input c_BB,\n    output reg [29:0] result,\n    output reg done\n);\n    localparam [2:0] IDLE = 3'b000;\n    localparam [2:0] DECODE = 3'b001;\n    localparam [2:0] COMPUTE_POWER = 3'b010;\n    localparam [2:0] COMPUTE_FIB = 3'b011;\n    localparam [2:0] DONE_STATE = 3'b100;\n\n    reg [2:0] state;\n    reg [3:0] N_reg;\n    reg [3:0] rule_code;\n    reg [1:0] rule_type;\n\n    reg [29:0] base;\n    reg [3:0] power_count;\n    wire [3:0] max_power = (N_reg >= 4'd3) ? N_reg - 4'd3 : 4'd0;\n    localparam [29:0] MOD = 30'd1000000007;\n\n    reg [29:0] fib_a, fib_b, fib_next;\n    reg [3:0] fib_count;\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            result <= 30'd0;\n            done <= 1'b0;\n            N_reg <= 4'd0;\n            rule_code <= 4'd0;\n            rule_type <= 2'b00;\n            base <= 30'd0;\n            power_count <= 4'd0;\n            fib_a <= 30'd0;\n            fib_b <= 30'd0;\n            fib_count <= 4'd0;\n        end else begin\n            done <= 1'b0;\n            case (state)\n                IDLE: begin\n                    if (start) begin\n                        N_reg <= N;\n                        rule_code <= {c_AA, c_AB, c_BA, c_BB};\n                        state <= DECODE;\n                    end\n                end\n\n                DECODE: begin\n                    case (rule_code)\n                        4'b0000,4'b0001,4'b0010,4'b0011,4'b0101,4'b0111,4'b1101,4'b1111: rule_type <= 2'b00;\n                        4'b0100,4'b1010,4'b1011,4'b1100: rule_type <= 2'b01;\n                        4'b0110,4'b1000,4'b1001,4'b1110: rule_type <= 2'b10;\n                        default: rule_type <= 2'b00;\n                    endcase\n\n                    if (rule_type == 2'b00 | N_reg < 4'd2) begin\n                        result <= 30'd1;\n                        state <= DONE_STATE;\n                    end else if (rule_type == 2'b01) begin\n                        if (N_reg < 4'd3) begin\n                            result <= 30'd1;\n                            state <= DONE_STATE;\n                        end else begin\n                            base <= 30'd1;\n                            power_count <= 4'd0;\n                            state <= COMPUTE_POWER;\n                        end\n                    end else begin\n                        if (N_reg < 4'd3) begin\n                            result <= 30'd1;\n                            state <= DONE_STATE;\n                        end else begin\n                            fib_a <= 30'd1;\n                            fib_b <= 30'd1;\n                            fib_count <= 4'd4;\n                            state <= COMPUTE_FIB;\n                        end\n                    end\n                end\n\n                COMPUTE_POWER: begin\n                    if (power_count < max_power) begin\n                        base <= (base << 1) % MOD;\n                        power_count <= power_count + 4'd1;\n                    end else begin\n                        result <= base;\n                        state <= DONE_STATE;\n                    end\n                end\n\n                COMPUTE_FIB: begin\n                    if (fib_count <= N_reg) begin\n                        fib_next <= (fib_a + fib_b) % MOD;\n                        fib_a <= fib_b;\n                        fib_b <= fib_next;\n                        fib_count <= fib_count + 4'd1;\n                    end else begin\n                        result <= fib_a;\n                        state <= DONE_STATE;\n                    end\n                end\n\n                DONE_STATE: begin\n                    done <= 1'b1;\n                    if (start == 1'b0) begin\n                        state <= IDLE;\n                    end\n                end\n\n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule